BEGIN;
CREATE TABLE ai_agents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,voice_profile_id uuid NOT NULL REFERENCES ai_voice_profiles(id),languages text[] NOT NULL,max_concurrent_calls integer NOT NULL CHECK(max_concurrent_calls>0),emotion_adaptation boolean NOT NULL DEFAULT false,meeting_handoff boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','published','paused','retired')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE ai_training_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ai_agent_id uuid NOT NULL REFERENCES ai_agents(id),source_type text NOT NULL CHECK(source_type IN('script','url','flow','document')),source_ref text NOT NULL,content_sha256 text,refresh_hours integer CHECK(refresh_hours BETWEEN 1 AND 720),state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','crawling','review','approved','rejected','retired')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_agent_routes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),did text NOT NULL,strategy text NOT NULL CHECK(strategy IN('intent','language','skill','segment','availability','weighted')),agent_ids uuid[] NOT NULL,fallback_agent_id uuid REFERENCES ai_agents(id),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,did));
CREATE TABLE ai_call_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ai_agent_id uuid NOT NULL REFERENCES ai_agents(id),campaign_id uuid REFERENCES campaigns(id),destination text NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','policy_review','dialing','connected','completed','failed','cancelled')),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),scheduled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE ai_agents ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_agents FORCE ROW LEVEL SECURITY;ALTER TABLE ai_training_sources ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_training_sources FORCE ROW LEVEL SECURITY;ALTER TABLE ai_agent_routes ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_agent_routes FORCE ROW LEVEL SECURITY;ALTER TABLE ai_call_jobs ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_call_jobs FORCE ROW LEVEL SECURITY;
CREATE POLICY ai_agents_isolation ON ai_agents USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY ai_training_sources_isolation ON ai_training_sources USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY ai_agent_routes_isolation ON ai_agent_routes USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY ai_call_jobs_isolation ON ai_call_jobs USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
